Otro sistema del taller: un concesionario debe etiquetar cada coche del inventario como "eléctrico" o "combustión" y como "premium" o "estándar" según el precio, sin modificar la ficha original del vehículo.

function etiquetarCoches(coches) {
  const salida = [];
  for (let i = 0; i < coches.length; i++) {
    const c = coches[i];
    const etiqueta = {
      ...c,
      motor: c.esElectrico ? 'eléctrico' : 'combustión',
      gama: c.precio > 40000 ? 'premium' : 'estándar'
    };
    salida.push(etiqueta);
  }
  return salida;
}

